package cn.cloudcurtain.tv;
import android.app.*;import android.content.*;import android.os.*;import androidx.media3.common.*;import androidx.media3.common.text.Cue;import androidx.media3.ui.SubtitleView;import androidx.media3.exoplayer.ExoPlayer;import java.lang.reflect.*;import java.util.*;import java.io.*;
final class TranslationLiveCheck{
 static Field field(Class<?> c,String name)throws Exception{Field f=c.getDeclaredField(name);f.setAccessible(true);return f;}
 static void run(Instrumentation test,Bundle result,boolean real)throws Exception{
  Context c=test.getTargetContext();MediaSpec spec;
  if(real){MovieLibrary.Movie film=null;for(MovieLibrary.Movie m:new MovieLibrary(c).movies())if(m.provider==Provider.QUARK&&Integer.toHexString(m.playbackKey().hashCode()).equals("22b1a8b1"))film=m;if(film==null)throw new IOException("Movie missing");spec=new CloudApi(Provider.QUARK).resolveCompatible(film.entry());}
  else{File file=new File(c.getCacheDir(),"subtitle-fixture.mkv");try(InputStream in=test.getContext().getAssets().open("subtitle-fixture.mkv");FileOutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}spec=new MediaSpec(android.net.Uri.fromFile(file).toString(),"真实字幕翻译测试");spec.key="fixture:translation";}
  c.getSharedPreferences("progress",0).edit().putLong(Integer.toHexString(spec.key.hashCode()),real?0:1200).commit();
  PlayerActivity a=(PlayerActivity)test.startActivitySync(new Intent(c,PlayerActivity.class).putExtra("media",spec.json()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  Field playerField=field(PlayerActivity.class,"player"),originalField=field(PlayerActivity.class,"originalSubtitles"),translationField=field(PlayerActivity.class,"translation");
  final ExoPlayer[] source={null};final TrackSelectionOverride[] english={null};final boolean[] sought={false};
  long start=SystemClock.elapsedRealtime();while(SystemClock.elapsedRealtime()-start<120000&&english[0]==null){Thread.sleep(300);test.runOnMainSync(()->{try{
   ExoPlayer main=(ExoPlayer)playerField.get(a);if(!real)main.pause();else if(!sought[0]){if(!main.isPlaying()||main.getDuration()<=0)return;sought[0]=true;main.seekTo(main.getDuration()/2);return;}OriginalSubtitles original=(OriginalSubtitles)originalField.get(a);ExoPlayer p=real?(original==null?null:original.player()):main;result.putInt("main_state",main.getPlaybackState());result.putLong("main_position",main.getCurrentPosition());result.putBoolean("main_sought",sought[0]);result.putBoolean("original_bridge",original!=null);if(original!=null){result.putString("original_error",original.failureCode);result.putLong("original_bytes",original.transferredBytes);}if(p==null)return;result.putInt("subtitle_state",p.getPlaybackState());result.putLong("subtitle_position",p.getCurrentPosition());result.putInt("subtitle_cues",p.getCurrentCues().cues.size());result.putInt("subtitle_groups",p.getCurrentTracks().getGroups().size());if(real){if(p.getPlaybackState()!=Player.STATE_READY||Math.abs(p.getCurrentPosition()-main.getCurrentPosition())>=1500)return;}
   for(Tracks.Group g:p.getCurrentTracks().getGroups())if(g.getType()==C.TRACK_TYPE_TEXT)for(int i=0;i<g.length;i++)if(g.isTrackSupported(i)&&g.getTrackFormat(i).language!=null&&g.getTrackFormat(i).language.startsWith("en")){result.putString("source_track_mime",g.getTrackFormat(i).sampleMimeType);result.putString("source_track_codecs",g.getTrackFormat(i).codecs);result.putString("source_track_id",g.getTrackFormat(i).id);source[0]=p;english[0]=new TrackSelectionOverride(g.getMediaTrackGroup(),i);}
  }catch(Exception e){throw new RuntimeException(e);}});}
  if(english[0]==null)throw new IOException("Real English subtitle track unavailable");
  Method begin=PlayerActivity.class.getDeclaredMethod("startTranslation",ExoPlayer.class,TrackSelectionOverride.class);begin.setAccessible(true);
  test.runOnMainSync(()->{try{begin.invoke(a,source[0],english[0]);}catch(Exception e){throw new RuntimeException(e);}});
  // Explicit user-level translation action above invokes the real configured Ark endpoint.
  final boolean[] rendered={false};start=SystemClock.elapsedRealtime();LiveTranslation live=null;
  while(SystemClock.elapsedRealtime()-start<60000&&!rendered[0]){
   Thread.sleep(250);live=(LiveTranslation)translationField.get(a);test.runOnMainSync(()->{try{SubtitleView view=(SubtitleView)field(PlayerActivity.class,"translatedView").get(a);List<Cue> cues=(List<Cue>)field(SubtitleView.class,"cues").get(view);for(Cue cue:cues)if(cue.text!=null&&cue.text.toString().matches("(?s).*[\u4e00-\u9fff].*")&&!cue.text.toString().contains("字幕无法辨认")&&view.isShown())rendered[0]=true;}catch(Exception e){throw new RuntimeException(e);}});
   if(live!=null&&!live.failureCode.isEmpty())break;
  }
  CaptionSamples captured=(CaptionSamples)field(PlayerActivity.class,"captions").get(a);result.putInt("captured_packets",captured.packets);result.putInt("captured_decoded",captured.decoded);result.putInt("captured_dropped",captured.dropped);result.putInt("captured_decode_failures",captured.decodeFailures);result.putLong("last_caption_duration_us",captured.lastDuration);synchronized(captured){Map<String,NavigableMap<Long,CaptionSamples.Line>> stored=(Map)field(CaptionSamples.class,"tracks").get(captured);result.putInt("captured_tracks",stored.size());String selected="original:"+english[0].mediaTrackGroup.getFormat(english[0].trackIndices.get(0)).id;NavigableMap<Long,CaptionSamples.Line> rows=stored.get(selected);result.putBoolean("captured_chosen_track",rows!=null);if(rows!=null&&!rows.isEmpty()){result.putInt("captured_rows",rows.size());int textLines=0;for(CaptionSamples.Line line:rows.values())if(!line.text.isEmpty())textLines++;result.putInt("captured_text_lines",textLines);for(CaptionSamples.Line line:rows.values())if(!line.image.isEmpty()){try(FileOutputStream png=new FileOutputStream(new File(c.getFilesDir(),"pgs-source.png"))){png.write(android.util.Base64.decode(line.image.substring(line.image.indexOf(",")+1),android.util.Base64.DEFAULT));}break;}result.putLong("captured_first",rows.firstKey());result.putLong("captured_last",rows.lastKey());}}
  if(live!=null){result.putInt("real_api_calls",live.calls);result.putInt("translated_segments",live.translatedLines);result.putString("translation_error",live.failureCode);}
  result.putBoolean("native_chinese_rendered",rendered[0]);if(!rendered[0])throw new IOException("Translated Chinese cue did not render");
  final String[] pausedText={""};final ExoPlayer[] mainPlayer={null};
  test.runOnMainSync(()->{try{mainPlayer[0]=(ExoPlayer)playerField.get(a);mainPlayer[0].pause();SubtitleView v=(SubtitleView)field(PlayerActivity.class,"translatedView").get(a);List<Cue> cues=(List<Cue>)field(SubtitleView.class,"cues").get(v);for(Cue cue:cues)if(cue.text!=null)pausedText[0]+=cue.text.toString();}catch(Exception e){throw new RuntimeException(e);}});
  Thread.sleep(2800);final boolean[] pauseKeepsTranslation={false};test.runOnMainSync(()->{try{SubtitleView v=(SubtitleView)field(PlayerActivity.class,"translatedView").get(a);List<Cue> cues=(List<Cue>)field(SubtitleView.class,"cues").get(v);String text="";for(Cue cue:cues)if(cue.text!=null)text+=cue.text.toString();pauseKeepsTranslation[0]=!text.isEmpty()&&text.equals(pausedText[0]);}catch(Exception e){throw new RuntimeException(e);}});
  if(!pauseKeepsTranslation[0])throw new IOException("Paused translated subtitle changed");result.putBoolean("pause_keeps_translation",true);
  android.graphics.Bitmap screenshot=test.getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),real?"quark-translated.png":"fixture-translated.png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{screenshot.recycle();}
  if(real){
   final boolean[] seekClears={false};test.runOnMainSync(()->{try{mainPlayer[0].seekTo(mainPlayer[0].getCurrentPosition()+120000);SubtitleView v=(SubtitleView)field(PlayerActivity.class,"translatedView").get(a);seekClears[0]=((List<?>)field(SubtitleView.class,"cues").get(v)).isEmpty();mainPlayer[0].play();}catch(Exception e){throw new RuntimeException(e);}});
   if(!seekClears[0])throw new IOException("Seek retained an old translated subtitle");result.putBoolean("seek_clears_old_translation",true);
   rendered[0]=false;start=SystemClock.elapsedRealtime();while(SystemClock.elapsedRealtime()-start<70000&&!rendered[0]){Thread.sleep(250);test.runOnMainSync(()->{try{SubtitleView v=(SubtitleView)field(PlayerActivity.class,"translatedView").get(a);List<Cue> cues=(List<Cue>)field(SubtitleView.class,"cues").get(v);for(Cue cue:cues)if(cue.text!=null&&cue.text.toString().matches("(?s).*[\\u4e00-\\u9fff].*")&&!cue.text.toString().contains("字幕无法辨认")&&mainPlayer[0].isPlaying())rendered[0]=true;}catch(Exception e){throw new RuntimeException(e);}});if(live!=null&&!live.failureCode.isEmpty())break;}
   final LiveTranslation checked=live;test.runOnMainSync(()->{try{OriginalSubtitles bridge=(OriginalSubtitles)originalField.get(a);result.putLong("after_seek_main_position",mainPlayer[0].getCurrentPosition());result.putInt("after_seek_main_state",mainPlayer[0].getPlaybackState());result.putBoolean("after_seek_main_playing",mainPlayer[0].isPlaying());if(bridge!=null){result.putLong("after_seek_caption_position",bridge.player().getCurrentPosition());result.putInt("after_seek_caption_state",bridge.player().getPlaybackState());result.putString("after_seek_caption_error",bridge.failureCode);}result.putInt("after_seek_api_calls",checked.calls);result.putString("after_seek_translation_error",checked.failureCode);result.putString("after_seek_translation_error_type",checked.failureType);result.putInt("after_seek_translated_segments",checked.translatedLines);result.putInt("after_seek_current_rows",captured.current("original:"+english[0].mediaTrackGroup.getFormat(english[0].trackIndices.get(0)).id,mainPlayer[0].getCurrentPosition()).size());}catch(Exception e){throw new RuntimeException(e);}});
   if(!rendered[0])throw new IOException("Translation did not resume at the new position");result.putBoolean("translation_resumes_after_seek",true);
  }
  final LiveTranslation selected=live;Method close=PlayerActivity.class.getDeclaredMethod("closeTranslation");close.setAccessible(true);
  test.runOnMainSync(()->{try{close.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});int calls=selected.calls;Thread.sleep(2000);if(selected.calls!=calls)throw new IOException("Translation kept calling after close");
  result.putBoolean("closed_stops_api_calls",true);test.runOnMainSync(a::finish);
 }
}
